"use strict";
// Preview tab: draws what the panel would show for the draft configuration.
// Content comes from the add-on's own card code (api/preview returns the exact
// commands it would send). Positions, sizes and field numbers come from the HMI
// project, via layouts/us-p.json (generated by scripts/gen_preview_layout.py).
// Fonts and the on/off switch graphic are approximations of the screen's own.
(() => {
  // Approximate pixel sizes for the screen's font ids 0-5.
  const FONT_PX = {0: 20, 1: 24, 2: 28, 3: 40, 4: 56, 5: 96};
  const SKIP = new Set(["tId", "tInstruction", "tTmp", "tSend", "p0"]);
  const DISABLED = 27501, BUTTON_TEXT = 1374, WHITE = 65535;
  let layoutPromise = null, data = null, current = "card:0", yamlText = "";

  function rgb(value) {
    const v = Number(value);
    if (!Number.isFinite(v)) return null;
    const r = Math.round(((v >> 11) & 31) * 255 / 31), g = Math.round(((v >> 5) & 63) * 255 / 63), b = Math.round((v & 31) * 255 / 31);
    return `rgb(${r},${g},${b})`;
  }
  function loadLayout() {
    layoutPromise ||= fetch("layouts/us-p.json").then(r => r.json()).then(d => d["us-p"]);
    return layoutPromise;
  }
  function component(screen, page, comp, text, options = {}) {
    const node = element("div", undefined, `pv-${comp.type.toLowerCase()}`);
    Object.assign(node.style, {left: `${comp.x}px`, top: `${comp.y}px`, width: `${comp.w}px`, height: `${comp.h}px`});
    const font = options.font ?? comp.font ?? 0;
    node.style.fontSize = `${FONT_PX[font] || 20}px`;
    const color = rgb(options.pco ?? comp.pco);
    if (color) node.style.color = color;
    const fill = options.bco ?? comp.bco;
    if (fill !== undefined && fill !== page.bco && comp.type !== "Button") node.style.background = rgb(fill);
    node.style.justifyContent = {left: "flex-start", right: "flex-end"}[comp.xcen] || "center";
    node.style.alignItems = {top: "flex-start", bottom: "flex-end"}[comp.ycen] || "center";
    node.style.textAlign = comp.xcen || "center";
    if (comp.wrap === false) {
      // Like the screen, a long single line is cut off at the end instead of being centred out of the box.
      Object.assign(node.style, {display: "block", whiteSpace: "nowrap", lineHeight: `${comp.h}px`});
    }
    if (text !== undefined && text !== null) setContent(node, String(text), options.icon);
    node.dataset.name = comp.name;
    screen.append(node);
    return node;
  }
  function setContent(node, text, isIcon) {
    const name = data && data.icons && data.icons[text];
    if (isIcon && name) {
      node.classList.add("mdi", `mdi-${name}`);
    } else node.textContent = text;
  }
  function byName(page) { return Object.fromEntries(page.components.map(c => [c.name, c])); }
  function newScreen(page) {
    const screen = element("div", undefined, "pv-screen");
    screen.style.background = rgb(page.bco ?? 0);
    return screen;
  }
  // Grid cells end icon text with "¬" plus a font id to force that font (HMI script).
  function gridIcon(text) {
    if (text.length >= 2 && text[text.length - 2] === "¬") return {text: text.slice(0, -2), font: text.charCodeAt(text.length - 1) - 48};
    return {text, font: undefined};
  }

  function drawNavigation(screen, page, comps, f) {
    for (const [name, at] of [["bPrev", 2], ["bNext", 8]]) {
      if (!comps[name] || !f[at] || f[at] === "delete") continue;
      component(screen, page, comps[name], f[at + 2], {icon: true, pco: Number(f[at + 3])});
    }
  }
  function drawSlotEntities(screen, page, comps, f) {
    for (let i = 1, base = 14; base < f.length && comps[`tEntity${i}`]; i += 1, base += 6) {
      const type = f[base];
      if (!type || type === "delete") continue;
      const [icon, color, name, value = ""] = [f[base + 2], f[base + 3], f[base + 4], f[base + 5]];
      component(screen, page, comps[`tIcon${i}`], icon, {icon: true, pco: Number(color)});
      component(screen, page, comps[`tEntity${i}`], name);
      if (type === "shutter") {
        const parts = value.split("|");
        [["bUp", 0, 3], ["bStop", 1, 4], ["bDown", 2, 5]].forEach(([prefix, index, state]) => {
          if (comps[`${prefix}${i}`]) component(screen, page, comps[`${prefix}${i}`], parts[index], {icon: true, pco: parts[state] === "disable" ? DISABLED : WHITE});
        });
      } else if (["light", "switch", "fan"].includes(type)) {
        if (comps[`btOnOff${i}`]) toggle(screen, comps[`btOnOff${i}`], value === "1");
      } else if (type === "text" || type === "timer") {
        component(screen, page, comps[`bText${i}`], value, {pco: WHITE});
      } else if (type === "button" || type === "input_sel") {
        component(screen, page, comps[`bText${i}`], value, {pco: BUTTON_TEXT});
      } else if (type === "number") {
        const [current, min = "0", max = "100"] = value.split("|").map(Number);
        slider(screen, comps[`hSlider${i}`], (current - min) / ((max - min) || 1));
        component(screen, page, comps[`nNum${i}`], Number.isFinite(current) ? current : "", {pco: WHITE});
      }
    }
  }
  function toggle(screen, comp, on) {
    const node = element("div", undefined, `pv-toggle${on ? " on" : ""}`);
    Object.assign(node.style, {left: `${comp.x}px`, top: `${comp.y + (comp.h - 26) / 2}px`, width: `${comp.w}px`});
    node.append(element("span"));
    screen.append(node);
  }
  function slider(screen, comp, fraction) {
    if (!comp) return;
    const node = element("div", undefined, "pv-slider");
    Object.assign(node.style, {left: `${comp.x}px`, top: `${comp.y + comp.h / 2 - 3}px`, width: `${comp.w}px`});
    const fill = element("span"); fill.style.width = `${Math.max(0, Math.min(1, fraction)) * 100}%`;
    node.append(fill); screen.append(node);
  }
  function drawGrid(screen, page, comps, f) {
    for (let i = 1, base = 14; base < f.length && comps[`bEntity${i}`]; i += 1, base += 6) {
      const type = f[base];
      if (!type || type === "delete") continue;
      const icon = gridIcon(f[base + 2] || "");
      component(screen, page, comps[`bEntity${i}`], icon.text, {icon: true, pco: Number(f[base + 3]), font: icon.font});
      if (comps[`tEntity${i}`]) component(screen, page, comps[`tEntity${i}`], f[base + 4]);
    }
  }
  function renderCard(layout, card) {
    const update = card.commands.find(c => c.startsWith("entityUpd~"));
    const page = layout[card.type] || layout.cardEntities;
    const screen = newScreen(page), comps = byName(page);
    if (!update) return screen;
    const f = update.split("~");
    if (comps.tHeading) component(screen, page, comps.tHeading, f[1]);
    drawNavigation(screen, page, comps, f);
    if (comps.bEntity1) drawGrid(screen, page, comps, f); else drawSlotEntities(screen, page, comps, f);
    return screen;
  }

  function applyBindings(screen, page, comps, bindings, fields) {
    for (const b of bindings || []) {
      const comp = comps[b.comp];
      if (!comp || SKIP.has(b.comp)) continue;
      const value = fields[b.field] ?? "";
      let node = screen.querySelector(`[data-name="${b.comp}"]`);
      if (!node) node = component(screen, page, comp);
      if (b.attr === "txt") setContent(node, value, /Icon/.test(b.comp));
      else if (value !== "" && rgb(value)) node.style.color = rgb(value);
    }
  }
  function renderScreensaver(layout, saver) {
    const page = layout[saver.type] || layout.screensaver;
    const screen = newScreen(page), comps = byName(page);
    const commands = saver.commands || [];
    const weather = commands.find(c => c.startsWith("weatherUpdate~"));
    const status = commands.find(c => c.startsWith("statusUpdate~"));
    if (weather) applyBindings(screen, page, comps, page.bindings && page.bindings.weatherUpdate, weather.split("~"));
    if (status) {
      const fields = status.split("~");
      applyBindings(screen, page, comps, page.bindings && page.bindings.statusUpdate, fields);
      [["tIcon1", 5], ["tIcon2", 6]].forEach(([name, at]) => {
        const node = screen.querySelector(`[data-name="${name}"]`);
        if (node && fields[at]) node.style.fontSize = `${FONT_PX[3]}px`;
      });
    }
    const [clock, ampm = ""] = (data.time || "").split("?");
    if (comps.tTime) component(screen, page, comps.tTime, clock);
    if (comps.tAMPM && ampm) component(screen, page, comps.tAMPM, ampm);
    if (comps.tDate) component(screen, page, comps.tDate, data.date || "");
    if (comps.t10) component(screen, page, comps.t10, "", {bco: WHITE});
    return screen;
  }

  function views() {
    const list = data.cards.map((card, index) => ({key: `card:${index}`, label: `${card.hidden ? "Hidden: " : ""}${card.title || card.type}`}));
    list.push({key: "saver", label: "Screensaver"});
    return list;
  }
  async function draw() {
    const root = $("preview-view");
    root.textContent = "";
    const layout = await loadLayout();
    const bar = element("div", undefined, "pv-bar");
    const select = element("select"); select.setAttribute("aria-label", "Panel");
    for (const name of data.panels) { const o = element("option", name); o.value = name; select.append(o); }
    select.value = data.panel || "";
    select.onchange = () => { selected = select.value; refresh(select.value).catch(e => message(e.message, true)); };
    bar.append(select);
    const list = views();
    if (!list.some(v => v.key === current)) current = list[0].key;
    const index = list.findIndex(v => v.key === current);
    const step = delta => { current = list[(index + delta + list.length) % list.length].key; draw(); };
    const prev = element("button", "Previous"); prev.type = "button"; prev.onclick = () => step(-1);
    const next = element("button", "Next"); next.type = "button"; next.onclick = () => step(1);
    const choose = element("select"); choose.setAttribute("aria-label", "Card");
    for (const v of list) { const o = element("option", v.label); o.value = v.key; choose.append(o); }
    choose.value = current; choose.onchange = () => { current = choose.value; draw(); };
    const again = element("button", "Refresh"); again.type = "button";
    again.onclick = () => refresh(select.value).catch(e => message(e.message, true));
    bar.append(prev, choose, next, again);
    root.append(bar);
    if (data.errors.length) root.append(element("p", data.errors.join("\n"), "pv-errors"));
    if (data.model && data.model !== "us-p") root.append(element("p", `Preview currently draws the US portrait panel; this panel is model ${data.model}.`, "pv-note"));
    const stage = element("div", undefined, "pv-stage");
    const picked = list.find(v => v.key === current);
    if (picked.key === "saver") stage.append(renderScreensaver(layout, data.screensaver));
    else stage.append(renderCard(layout, data.cards[Number(picked.key.split(":")[1])]));
    root.append(stage);
    root.append(element("p", "Approximate preview: text and icons are exactly what the panel will be sent, using current Home Assistant states. Fonts and the on/off switch are drawn approximately.", "pv-note"));
  }
  async function refresh(panel) {
    data = await api("preview", {yaml: yamlText, panel: panel || null});
    await draw();
  }
  window.showPreview = async (yaml, panel) => {
    yamlText = yaml;
    $("preview-view").textContent = "Rendering preview...";
    await refresh(panel);
  };
})();
